      const names = Object.keys(G), ord = ['Dendrit', 'Hücre gövdesi', 'Ranvier boğumu', 'Miyelin kılıf', 'Akson ucu', 'Çekirdek', 'Akson'];
      selTable(box, 'e5_u3', ['No', 'Yapının adı', 'Yapının görevi'], ord.map((n, i) => ({ l: (i + 1) + '. (' + ['dendrit dalları', 'gövde', 'kılıflar arası boşluk', 'sarı kılıf', 'dallanan uç', 'gövdenin merkezi', 'uzun uzantı'][i] + ')', f: [{ o: names, a: n }, { o: names.map(k => G[k]), a: G[n] }] })));
